deploy.startCommand:
node -e '
const https = require("https");
const url = require("url");

const n8nBase = "https://n8n-production-806e.up.railway.app";
const enquiryId = "8ceda31e-e9de-4c87-9d91-1a78b728a9b4";
const sessionId = "demo-1788675782890-37898";
const timestamp = Date.now();
const testMsg = `Test msg ${timestamp}`;

function post(path, body) {
  return new Promise((resolve, reject) => {
    const u = url.parse(`${n8nBase}${path}`);
    const req = https.request({
      hostname: u.hostname,
      path: u.path,
      method: "POST",
      headers: {"Content-Type": "application/json"},
      timeout: 10000
    }, (res) => {
      let data = "";
      res.on("data", chunk => data += chunk);
      res.on("end", () => resolve({status: res.statusCode, body: data}));
    });
    req.on("error", reject);
    req.setTimeout(10000, () => {req.destroy(); reject(new Error("timeout"))});
    req.write(JSON.stringify(body));
    req.end();
  });
}

(async () => {
  try {
    // Step 1: Take over
    console.log("[TEST] Step 1: POST /webhook/favfare-demo/crm (action=staff_action, take_over)");
    let res = await post("/webhook/favfare-demo/crm", {
      action: "staff_action",
      action_type: "take_over",
      enquiry_id: enquiryId
    });
    console.log(`[TEST] Step 1 status: ${res.status}`);
    let hasAutomationPausedTrue = res.body.includes("automation_paused\":true") || res.body.includes("\"automation_paused\": true");
    console.log(hasAutomationPausedTrue ? "[TEST] PASS: automation_paused=true" : `[TEST] FAIL: automation_paused not true in: ${res.body.substring(0, 200)}`);

    // Step 2: Chat while paused
    console.log("[TEST] Step 2: POST /webhook/favfare-demo/patient-action-v9 (action=chat, paused)");
    res = await post("/webhook/favfare-demo/patient-action-v9", {
      session_id: sessionId,
      action: "chat",
      message: testMsg,
      history: []
    });
    console.log(`[TEST] Step 2 status: ${res.status}`);
    let hasAssistantReply = res.body.includes("<div class=\"assistant") || res.body.includes("assistant");
    console.log(hasAssistantReply ? "[TEST] FAIL: assistant reply found despite takeover" : "[TEST] PASS: no assistant reply during takeover");

    // Step 3: Return to assistant (always execute)
    console.log("[TEST] Step 3: POST /webhook/favfare-demo/crm (action=staff_action, return_to_assistant)");
    res = await post("/webhook/favfare-demo/crm", {
      action: "staff_action",
      action_type: "return_to_assistant",
      enquiry_id: enquiryId
    });
    console.log(`[TEST] Step 3 status: ${res.status}`);
    let hasAutomationPausedFalse = !res.body.includes("automation_paused\":true") && !res.body.includes("\"automation_paused\": true");
    console.log(hasAutomationPausedFalse ? "[TEST] PASS: automation_paused=false" : `[TEST] FAIL: automation_paused still true: ${res.body.substring(0, 200)}`);

    // Step 4: Chat after resume
    console.log("[TEST] Step 4: POST /webhook/favfare-demo/patient-action-v9 (action=chat, resumed)");
    res = await post("/webhook/favfare-demo/patient-action-v9", {
      session_id: sessionId,
      action: "chat",
      message: testMsg + " resumed",
      history: []
    });
    console.log(`[TEST] Step 4 status: ${res.status}`);
    hasAssistantReply = res.body.includes("<div class=\"assistant") || res.body.includes("assistant");
    console.log(hasAssistantReply ? "[TEST] PASS: assistant reply resumed" : "[TEST] FAIL: no assistant reply after resume");

    console.log("[TEST] One-shot test complete");
  } catch (err) {
    console.error("[TEST] ERROR:", err.message);
    try {
      console.log("[TEST] Step 3b: Attempting cleanup POST return_to_assistant");
      await post("/webhook/favfare-demo/crm", {
        action: "staff_action",
        action_type: "return_to_assistant",
        enquiry_id: enquiryId
      });
      console.log("[TEST] Cleanup complete");
    } catch (cleanupErr) {
      console.error("[TEST] Cleanup failed:", cleanupErr.message);
    }
    process.exit(1);
  }
})();
'
